#pragma once

#include "MacScopeNativeDecompiler/Backend.hpp"

#include <cstddef>
#include <filesystem>
#include <functional>
#include <memory>
#include <stdexcept>
#include <string>
#include <string_view>

namespace macscope::native_decompiler::detail {

class GhidraDirectoryIdentityLease;

/// Values generated by CMake only after the complete materialization has been
/// verified and before any upstream package configuration is evaluated.
struct GhidraPackageAttestationExpectations final {
    std::filesystem::path materializationRoot;
    std::string materializationManifestSha256;
    std::string packageTreeSha256;
    std::filesystem::path packageRoot;
    std::filesystem::path globalProcessorSpecRoot;
    std::filesystem::path processorSpecRoot;
};

/// Canonical, revalidated paths that may be used to acquire the process-global
/// native runtime. No value in this record is suitable for diagnostics.
struct GhidraPackageAttestation final {
    std::filesystem::path materializationRoot;
    std::string materializationManifestSha256;
    std::string packageTreeSha256;
    std::filesystem::path packageRoot;
    std::filesystem::path globalProcessorSpecRoot;
    std::filesystem::path processorSpecRoot;
    std::shared_ptr<const GhidraDirectoryIdentityLease> directoryIdentity;
};

/// Revalidate both retained directory identity and the metadata identity of
/// every member of the closed materialization tree. This performs no content
/// hashing and emits only stable, path-free failure slugs. The final current-
/// path check narrows directory replacement during validation, but each member
/// scan is still a metadata snapshot: mutation after a member's final
/// observation, or before a later path-based upstream open, is not claimed to
/// be immutable. That stronger boundary belongs to DCP-04 isolation.
void revalidateGhidraPackageDirectories(const GhidraPackageAttestation& attestation);

/// Private synthetic-test surface for the same closed-tree identity lease used
/// by production package attestations. This header is not part of the public B4
/// include surface.
[[nodiscard]] std::shared_ptr<const GhidraDirectoryIdentityLease>
captureGhidraClosedTreeIdentityForTesting(const std::filesystem::path& root);

void revalidateGhidraClosedTreeIdentityForTesting(
    const std::shared_ptr<const GhidraDirectoryIdentityLease>& identity
);

void revalidateGhidraClosedTreeIdentityForTesting(
    const std::shared_ptr<const GhidraDirectoryIdentityLease>& identity,
    const std::function<void(std::string_view)>& memberObserver
);

[[nodiscard]] std::size_t ghidraClosedTreeMaximumMembersForTesting() noexcept;
[[nodiscard]] std::size_t ghidraClosedTreeMaximumPathBytesForTesting() noexcept;
[[nodiscard]] bool ghidraClosedTreeMemberBudgetExceededForTesting(
    std::size_t members
) noexcept;
[[nodiscard]] bool ghidraClosedTreePathBudgetExceededForTesting(
    std::size_t bytes
) noexcept;

/// Bounded failure carrying a stable reason code and no host path. Provider
/// availability may publish reasonCode(); what() deliberately returns the same
/// path-free slug.
class GhidraPackageAttestationError final : public std::runtime_error {
public:
    explicit GhidraPackageAttestationError(std::string_view reasonCode);

    [[nodiscard]] const std::string& reasonCode() const noexcept;

private:
    std::string reasonCode_;
};

/// Revalidate the exact canonical MATERIALIZATION.json bytes, manifest shape,
/// package layout, every ordinary package member, and the Python-contract tree
/// digest before any native global state is initialized.
[[nodiscard]] GhidraPackageAttestation attestGhidraPackage(
    const GhidraBackendConfiguration& configuration,
    const GhidraPackageAttestationExpectations& expectations
);

} // namespace macscope::native_decompiler::detail
